WITH RecentStores AS (SELECT *, CASE WHEN sqft >= 16629 THEN 'High' WHEN sqft >= 6196 THEN 'Medium' ELSE 'Low' END sqft_level FROM stores WHERE sqft BETWEEN 6532 AND 10242), stores_stats AS (SELECT region, AVG(sqft) avg_sqft, MIN(sqft) min_sqft FROM RecentStores GROUP BY region) SELECT region, min_sqft FROM stores_stats WHERE avg_sqft > 13200 ORDER BY min_sqft DESC, region ASC LIMIT 10
